// Notes for HR, plus pay and joining terms. Matched by designation (positions.id). HR's saved
// versions in ats_job_templates replace these; deleting HR's version brings the default back.
// Text fields are plain text: blank line between paragraphs, "• " bullets, short heading lines.
import type { JobTemplateDefault } from "./jobTemplates";

